import math

ITEM_KB = 7
READS_PER_SEC = 100
WRITES_PER_SEC = 20

def read_rcu(item_kb, strong=True):
    units = math.ceil(item_kb / 4)
    return units if strong else math.ceil(units / 2)

def write_wcu(item_kb):
    return math.ceil(item_kb / 1)

print(f"item_size={ITEM_KB}KB reads={READS_PER_SEC}/s writes={WRITES_PER_SEC}/s")
print(f"strong_read_rcu={read_rcu(ITEM_KB, True) * READS_PER_SEC}")
print(f"eventual_read_rcu={read_rcu(ITEM_KB, False) * READS_PER_SEC}")
print(f"wcu={write_wcu(ITEM_KB) * WRITES_PER_SEC}")
